from pathlib import Path
import json,re,datetime
R=Path(__file__).resolve().parents[1]
SHA='2dcca11fda764949d36f6f174bd72ccc2a83c2863f522635e7afd8539d88f84c'
qs=[];cs=[];by_page={}
def add(p,topic,stem,options,correct,why,explanations,memory=None,typ='conceptual',difficulty='medium',assumptions=None,steps=None,formulas=None,more_pages=None):
    pages=[p]+(more_pages or [])
    n=by_page.get(p,0)+1;by_page[p]=n
    qid=f'W01-L01-P{p:04d}-Q{n:02d}';cid=qid.replace('-Q','-C')
    if isinstance(correct,int):correct=[correct]
    citations=[]
    for pg in pages:
        txt=(R/f'sources/text/lectures/page-{pg:04d}.txt').read_text().strip()
        txt=re.sub(r'\s+\d+\s*$','',txt).strip()
        citations.append({'slideId':f'lectures-p{pg:04d}','sourceId':'lectures','sourceSha256':SHA,'physicalPage':pg,'kind':'figure' if typ=='diagram' else 'equation' if typ=='numerical' else 'statement','locator':f'Lecture 1 physical PDF page {pg}; ' + ('no visible printed slide number' if pg==27 else f'printed slide {pg}') + '; main text and associated figure','evidenceText':txt,'role':'premise' if typ=='numerical' else 'explicit','region':None})
    q={'id':qid,'version':1,'status':'draft','authorId':'robotics-integration-author','stem':stem,'selectionMode':'multi' if len(correct)>1 else 'single','type':typ,'difficulty':difficulty,'cognitiveSkill':'recall' if typ=='definition' else ('numerical' if typ=='numerical' else 'application' if typ=='scenario' else 'conceptual'),'week':1,'lectureId':'L01','topic':'Introduction to Robotics','subtopic':topic,'tags':[topic],'conceptIds':[cid],'assumptions':assumptions or [],'options':[{'id':f'o{i+1}','text':s} for i,s in enumerate(options)],'correctOptionIds':[f'o{i+1}' for i in correct],'citations':citations,'solution':{'justification':why,'optionExplanations':{f'o{i+1}':s for i,s in enumerate(explanations)},'steps':steps or [],'formulas':formulas or [],'simpleExplanation':why,'memoryAid':memory,'misconceptions':[s for i,s in enumerate(explanations) if i not in correct],'examTraps':['Read the stated scope and assumptions; do not replace the cited course convention with a broader claim.'],'prerequisiteConceptIds':[]},'origin':'generated','reviewIds':[]}
    shift=len(qs)%len(q['options']); q['options']=q['options'][shift:]+q['options'][:shift]
    qs.append(q);cs.append({'id':cid,'title':topic+': '+stem[:90],'description':why,'slideIds':[f'lectures-p{pg:04d}' for pg in pages],'questionIds':[qid],'status':'drafted','topic':'Introduction to Robotics','subtopic':topic,'prerequisiteConceptIds':[],'examinationAngles':[typ]})

add(15,'Robot definition','Which description matches the course definition of a robot?', ['A reprogrammable integration of mechanical, electrical and software components','Any mechanical device that moves, even if it cannot be reprogrammed','A software-only system with no physical components','A machine that must always act without human intervention'],0,'The slide defines a robot through integrated mechanical, electrical and software components and the ability to be reprogrammed.', ['This includes all three component groups and reprogrammability.','Movement alone omits the integration and reprogrammability conditions.','The definition includes mechanical and electrical components, not only software.','The definition explicitly allows operation with or without human intervention.'],'Robot = mechanics + electrics + software + reprogramming.',typ='definition',difficulty='easy')
add(15,'Human intervention','A remotely operated robot follows human commands; does human involvement alone rule it out under the slide definition?', ['No; the definition permits tasks with or without human intervention','Yes; a robot must be fully autonomous','Yes; all reprogramming must occur without humans','No, but only if the machine has exactly six joints'],0,'Human intervention is compatible with the stated definition of a robot.', ['Both supervised and autonomous operation fit the definition.','Autonomy is not a necessary condition in this definition.','The source does not impose autonomous reprogramming.','The definition does not specify a joint count.'],typ='scenario')
add(15,'Robotics definition','Which three activities form the stated scope of robotics?', ['Design, programming and control','Painting, welding and assembly only','Transport, storage and sales','Sensing alone, without mechanical design'],0,'Robotics is defined as the study of robot design, programming and control.', ['These are the three named activities.','These are applications, not the stated discipline definition.','These are logistics/business activities, not the three stated areas.','Sensing is relevant but is not the full scope.'],typ='definition',difficulty='easy')
add(15,'History and terminology','Which pairing follows the slide account of the word robot?', ['Slavic roots; work or drudgery','Latin roots; mathematical proof','Greek roots; self-awareness','English roots; electrical circuit'],0,'The slide associates the Slavic word with worker, compulsory work and drudgery.', ['This matches the stated root and meanings.','Neither the stated root nor meaning matches.','The slide does not give this etymology.','Electrical circuitry is not the word meaning stated.'],typ='definition',difficulty='easy')
add(15,'History and terminology','According to the slide, who popularized robot for intelligent machines, in which work and year?', ['Karel Čapek; R.U.R.; 1920','George Devol; R.U.R.; 1962','Joseph Engelberger; I, Robot; 1920','Isaac Asimov; R.U.R.; 1985'],0,'The slide attributes the usage to Czech playwright Karel Čapek in Rossum’s Universal Robots, 1920.', ['All three details match the source.','Devol belongs to the commercial-robot account, not this play.','Engelberger is not the playwright named on this slide.','Asimov is associated with the later laws discussion, not the stated play.'],typ='definition')
add(16,'First commercial robot','What year does the course slide explicitly give for the first commercial robot?', ['1962','1920','1942','1985'],0,'This question asks only for the year printed on the course slide: 1962; it does not claim to resolve all historical date conventions.', ['1962 is the date printed in the first bullet.','1920 is associated with the play R.U.R. in the previous slide.','The slide does not give 1942 for the first commercial robot.','1985 appears in the sketch attribution, not the introduction date.'],typ='definition',assumptions=['Answer according to the printed course slide; this is a source-specific historical claim.'])
add(16,'First commercial robot','Which complete combination is stated for the first commercial robot?', ['Unimation Inc.; Engelberger and Devol; General Motors plant','KUKA; Čapek and Asimov; IIT Roorkee','General Motors; Craig and Govers; Unimation plant','ROBOTINO; Engelberger and Čapek; Boston Dynamics'],0,'The slide names Unimation Inc., its founders Joseph F. Engelberger and George Devol, and a General Motors installation.', ['Every part agrees with the slide.','These names and organization do not match the stated account.','General Motors is the installation site, not the named developer.','This combines unrelated examples and people.'],typ='statement')
add(16,'First commercial robot','Who is labeled Father of Robotics on this slide?', ['Joseph F. Engelberger','George Devol','Karel Čapek','J. J. Craig'],0,'The parenthetical label follows Joseph F. Engelberger’s name.', ['The label is printed after Engelberger.','Devol is described as the inventor and cofounder, not given this label here.','Čapek is discussed for terminology, not this label.','Craig is a cited textbook author, not the person labeled here.'],typ='definition',difficulty='easy')
add(16,'Unimate diagram','In the Unimate sketch, which label identifies extension or retraction along the long arm?', ['Radial motion','Wrist yaw','Wrist swivel','Rotary motion'],0,'The radial-motion arrow runs along the arm, unlike the angular motion arrows.', ['The diagram places this arrow along the arm’s length.','Wrist yaw is an angular movement at the wrist.','Wrist swivel is a wrist rotation, not arm extension.','The rotary-motion label is located at the rear rotating assembly.'],typ='diagram')
add(17,'Mobility and manipulation','Which matching is correct in the course classification?', ['Mobility → transport; manipulation → action on the environment','Mobility → action on the environment; manipulation → transport only','Mobility → no movement; manipulation → no contact','Mobility → learning only; manipulation → sensing only'],0,'The slide classifies the main goals as transport for mobility and environmental action for manipulation.', ['Both goals match.','The stated primary goals are reversed.','The definition does not equate either class with absence of movement/contact.','These goals are not the ones stated.'],'Move the robot versus act on the world.',typ='match',difficulty='easy')
add(18,'Mobile robot selection','For the examples on the slide, which robot type is associated with uneven terrain?', ['Walking or running robots with legs','Wheeled robots specifically described for flat surfaces','Only fixed-base manipulators','Only stationary SCARA arms'],0,'Walking and running robots are stated to handle uneven terrain, whereas the wheeled example is associated with flat surfaces.', ['This is the stated terrain association.','This reverses the slide’s flat/uneven comparison.','A fixed-base manipulator is not the mobile type described.','SCARA is introduced as an assembly manipulator, not this terrain example.'],typ='scenario',difficulty='easy')
add(18,'Mobile robot examples','Which image-label pairing matches the supplied mobile-robot slide?', ['ROBOTINO is the wheeled example; BIGDOG is the legged example','ROBOTINO is the legged example; BIGDOG is the wheeled example','Both examples are fixed industrial arms','Both examples are underwater vehicles'],0,'The slide places ROBOTINO under the wheeled platform and BIGDOG under the four-legged robot.', ['Both labels match the images.','The labels are reversed.','The pictures are mobile robots, not fixed arms.','Neither is presented as underwater.'],typ='diagram')
add(19,'Manipulator applications','Select all statements explicitly supported by the manipulator-examples slide.', ['Medical robots are presented as teleoperated','Painting raises coverage and path-planning issues','Industrial robots can be teleoperated or autonomous','All industrial robots are necessarily autonomous'],[0,1,2],'The first three statements reproduce the distinctions stated on the slide; the final absolute statement contradicts the two listed modes.', ['The medical example is labeled teleoperated.','Coverage and path planning are specifically named for painting.','Both modes are printed for industrial robots.','The slide explicitly includes teleoperated industrial robots.'],typ='statement')
add(20,'Robot classification','Which item is NOT one of the classification dimensions listed on the slide?', ['Customer payment method','Fixed versus mobile','Serial versus parallel','Rigid versus flexible'],0,'The listed dimensions concern mechanical arrangement, mobility, degrees of freedom and control; payment method is not one.', ['It does not appear among the robot classifications.','This is listed.','This is listed.','This is listed.'],typ='exception',difficulty='easy')
add(20,'Industrial robot structure','Which description matches most older industrial robots in the slide?', ['A fixed base with links joined by actuated joints','A flying base with no links','A software controller with no actuators','An underwater vehicle with no joints'],0,'The slide describes fixed bases and links connected by actuated joints.', ['This reproduces the structural description.','Flying robots are mentioned among modern mobility possibilities, not the older-arm description.','The description explicitly includes actuated joints.','This does not match the described fixed-base arms.'],typ='definition',difficulty='easy')
add(21,'Serial and parallel robots','Which feature identifies the serial robot in the slide?', ['Links and joints connected sequentially from a fixed base to an end-effector','Several closed loops supporting a moving platform','No joints between neighboring links','A body that must move on wheels'],0,'The serial example is a sequential chain from its base to its end-effector.', ['This is the stated serial-chain structure.','The multiple-loop structure is associated with the parallel example.','The serial structure explicitly includes joints.','Wheeled mobility is a different classification dimension.'],typ='definition')
add(21,'Parallel mechanism figure','In the parallel-mechanism drawing, what is joined to the fixed base through several extensible legs?', ['The top platform','Only a single serial-chain wrist','The robot’s display screen','A free-floating object without joints'],0,'The drawing labels a top platform, fixed base and multiple extensible legs with joints.', ['This matches the figure’s structure and labels.','The picture is not a single open serial chain.','There is no display screen in this mechanism drawing.','The platform is mechanically connected through the legs.'],typ='diagram')
add(22,'Degrees of freedom','Under the slide’s generic rigid-pose task convention in three-dimensional space, how many DOF are required?', ['Six','Three','Four','Exactly eight'],0,'The slide states six DOF for an arbitrary task in 3D; this question uses that full position-and-orientation task convention.', ['Six is the source’s generic full-pose figure.','Three describes position only, not arbitrary position and orientation.','Four is associated with the specialized SCARA assembly example.','The source does not require eight for an arbitrary task.'],typ='definition',assumptions=['The task requires arbitrary position and orientation in 3D; this is not a claim that every restricted task needs six DOF.'])
add(22,'Task-specific DOF','Which task–DOF association follows the examples on the slide?', ['Electronic assembly: four-DOF SCARA; some painting/welding: five DOF','Electronic assembly: five-DOF SCARA; all painting: one DOF','Every painting task needs more than six DOF','Every task needs exactly the same number of DOF'],0,'The slide contrasts four-DOF SCARA assembly with painting/welding that can be done by a five-DOF robot.', ['Both example associations match.','The stated SCARA figure is four, not five; no one-DOF painting claim is given.','The source explicitly gives a five-DOF example.','The examples illustrate that task requirements differ.'],typ='match',assumptions=['Interpret these as course examples, not universal requirements for every assembly, painting or welding task.'])
add(22,'Redundancy','Why does the slide describe a robot with more than six DOF as useful?', ['It can add flexibility for obstacle avoidance','It removes the need for any actuator','It makes every possible pose automatically reachable','It guarantees a unique inverse-kinematics solution'],0,'The stated benefits are obstacle avoidance and greater flexibility, not universal guarantees about reachability or uniqueness.', ['This is the explicit stated purpose of redundancy.','Additional DOF do not imply no actuators.','The slide does not make universal reachability claims.','The source does not say redundancy guarantees uniqueness.'],typ='conceptual')
add(22,'Added mobility','What reason does the slide give for mounting a five- or six-DOF arm on a gantry or mobile base?', ['Extra flexibility or working volume','Eliminating all joint sensors by definition','Reducing every task to one-dimensional motion','Guaranteeing perfect accuracy'],0,'The slide explicitly motivates added base/gantry DOF by flexibility and working volume.', ['This is the printed reason.','Sensor elimination is not stated.','Adding movement does not impose one-dimensional motion.','Perfect accuracy is not claimed.'],typ='scenario')
add(23,'Joint arrangement','Which description is associated with an anthropomorphic robot?', ['A human-arm-like arrangement','Motion that is only Cartesian translation','A mechanism with no joints','A robot that must understand speech'],0,'Anthropomorphic is used for the human-arm-like mechanical arrangement.', ['This is the source definition.','Cartesian is a different listed arrangement.','The classification concerns joint arrangements.','Speech capability does not define this mechanical term.'],typ='definition',difficulty='easy')
add(23,'SCARA','Which expansion is actually printed for SCARA in this course slide?', ['Selective Compliance Adaptive Robot Arm','Serial Cartesian Autonomous Rotary Actuator','Spherical Control and Rotational Arm','Sensor-Controlled Artificial Robotic Agent'],0,'The source prints Selective Compliance Adaptive Robot Arm; the question intentionally asks for its exact course wording.', ['This is the expansion printed on the supplied slide.','This is not the printed expansion.','This is not the printed expansion.','This is not the printed expansion.'],typ='definition',assumptions=['Use the exact expansion printed by this course rather than another possible textbook expansion.'])
add(23,'Wrist orientation','What is the stated role of the last three joints in the illustrated serial-arm convention?', ['They form a wrist that orients the end-effector','They always translate the base without rotation','They remove the need for an end-effector','They determine the spelling of the robot’s coordinate system'],0,'The slide identifies the last three joints as the wrist and assigns it the end-effector orientation role.', ['This matches the stated wrist function.','The source does not describe base translation here.','The wrist orients an end-effector; it does not eliminate it.','Coordinate names do not define the wrist’s function.'],typ='definition',assumptions=['Use the serial-arm arrangement described on the slide, not a universal claim about all robots.'])
add(24,'Rigid and flexible design','Which trade-off is emphasized by the rigid-versus-flexible slide?', ['Industrial accuracy motivates rigidity; space weight reduction can motivate flexible links and joints','All flexible robots are more accurate in every task','Space applications require maximum mass regardless of performance','Industrial manipulators must always have flexible joints'],0,'The comparison links heavy rigid industrial structures with accuracy and lightweight space structures with flexibility.', ['This preserves the two stated design motivations.','The slide makes no universal accuracy guarantee for flexibility.','The slide says space applications seek to minimize weight.','The slide says most industrial robots are built heavy and rigid.'],typ='conceptual')
add(25,'Teach and playback','Which sequence describes teach-and-playback operation?', ['Manually guide and record positions, then replay the taught sequence','Randomly generate torque commands, then discard all recordings','Learn a new environment automatically before every playback step','Only enter CAD data without ever recording positions'],0,'Teach-and-playback records a manually guided task and replays that sequence during operation.', ['This follows the described teaching and execution stages.','The source describes recording, not discarding positions.','Automatic environmental learning is not a teach-and-playback property here.','This describes neither the manual teaching nor recorded playback.'],typ='sequence')
add(25,'Teach and playback limits','Which limitation is explicitly assigned to teach-and-playback on this slide?', ['Teaching is time-consuming and playback cannot react to environmental changes','It always requires no teaching time','It necessarily learns every new obstacle automatically','It cannot store any position information'],0,'The slide states that teaching takes time and the taught sequence does not react to environmental changes.', ['Both limitations are named.','This contradicts the time-consuming teaching statement.','Environmental learning is contrasted with intelligent control.','The teaching process explicitly records positions.'],typ='conceptual')
add(25,'Control modes','Which matching preserves the distinctions in the control-mode slide?', ['Sensor-driven: uses sensors for decisions; intelligent: learns about the environment using AI','Sensor-driven: cannot detect obstacles; intelligent: only replays a recording','Computer-controlled: must be manually moved at every instant; sensor-driven: has no sensors','Intelligent: has no software; computer-controlled: has no input'],0,'Sensor-based decisions and AI-based learning are distinguished from playback and computer-supplied programs.', ['Both stated functions match.','These negate the described abilities.','These descriptions contradict the named control modes.','These statements are not supported by the slide.'],typ='match')
add(26,'Asimov law priority','Under the slide’s fictional three-law hierarchy, which action has the highest priority?', ['Avoid harming humans','Obey every human instruction regardless of harm','Protect the robot even when that harms humans','Treat self-protection and human safety as equal priorities'],0,'The second and third laws are explicitly conditional on the earlier laws, so human safety is first.', ['This is the first law and constrains the later ones.','Obedience is restricted by the first law.','Self-protection must not violate the other laws.','The slide gives an ordered hierarchy rather than equal priorities.'],'Human safety before obedience before self-protection.',typ='conceptual',assumptions=['This is a question about Asimov’s fictional laws as summarized in the slide, not real-world safety certification.'])
add(26,'Asimov law conflict','A human orders a fictional robot to damage itself, and no human will be harmed; which slide-law relationship applies?', ['Obedience outranks self-protection if the first law is not violated','Self-protection always outranks obedience','The third law permits harming humans to preserve the robot','All three laws become irrelevant when an order is given'],0,'The third law protects the robot only when that protection does not violate the preceding laws.', ['The second law controls the case under the stated no-human-harm assumption.','This reverses the second/third-law priority.','The third law must not violate human safety.','An instruction does not cancel the hierarchy.'],typ='scenario',assumptions=['Apply only the simplified fictional law hierarchy shown on the slide.','No human is harmed by complying with the order.'])
add(27,'Pose and frames','Which two attributes describe an object in the slide’s spatial description?', ['Position and orientation','Mass and price','Color and manufacturer','Force and electrical resistance'],0,'A body’s spatial description is expressed by its position and orientation relative to a chosen frame.', ['These are the stated spatial attributes.','These are not the stated pose attributes.','These do not specify spatial pose.','These quantities do not replace position and orientation.'],typ='definition',difficulty='easy')
add(27,'Coordinate frames','Why is a coordinate frame rigidly attached to an object in the slide?', ['To describe its position and orientation relative to a reference frame','To make its physical position independent of all motion','To guarantee that all observers use identical numerical coordinates','To remove the need for any coordinate transformation'],0,'Rigid attachment ties the frame to the body; transformations express the same body relative to another reference.', ['This states the representational purpose.','Attaching a frame does not prevent physical motion.','Different reference frames can give different coordinate descriptions.','The slide explicitly motivates transformations between frames.'],typ='conceptual')
add(28,'Kinematics versus dynamics','Which question belongs to kinematics as defined on the slide?', ['How does the end-effector velocity change with joint motion?','What actuator force causes the motion?','What torque is required to overcome link inertia?','What contact force must an actuator generate?'],0,'Kinematics studies motion without regard to the forces causing it, including velocity and acceleration.', ['It asks about motion relationships, not their force causes.','This asks about a cause of motion and belongs to dynamics.','This asks about required torque and inertia.','This asks about force generation rather than motion geometry.'],typ='conceptual')
add(28,'Kinematic quantities','Which selection contains only quantities explicitly included in the study of kinematics?', ['Position, velocity and acceleration','Position, torque and payload mass','Friction force, motor torque and price','Contact force, mass and stiffness'],0,'The slide includes position, velocity, acceleration and higher derivatives among motion quantities.', ['All three are explicitly included.','Torque and mass are not the listed motion quantities.','These do not form the stated kinematic set.','These are not the listed kinematic motion variables.'],typ='definition')
add(29,'Joint variables','Which pairing is correct?', ['Revolute joint → joint angle; prismatic joint → translational joint offset','Revolute joint → translational offset; prismatic joint → joint angle','Both joint types must have an angular displacement only','Both joint types have no measurable displacement'],0,'Rotary/revolute displacement is an angle; sliding/prismatic displacement is a translation or joint offset.', ['Both associations match the slide.','The associations are reversed.','Prismatic displacement is translational.','The slide describes position sensors measuring relative displacement.'],'Revolute rotates; prismatic slides.',typ='match',difficulty='easy')
add(29,'Joint sensing','What do the described joint position sensors measure?', ['The relative position of neighboring links','Only the global position of every object in the room','Only the manufacturing cost of the arm','The next intended task without any program'],0,'The source locates sensors at joints to measure relative positions of neighboring links.', ['This is the stated measurement.','The joint sensors are not described as global room-mapping systems.','Cost is not a position measurement.','The sensors measure a physical state, not an unspecified intention.'],typ='definition',difficulty='easy')
add(30,'Forward kinematics','Given joint angles, what does the forward-kinematics problem compute?', ['Tool-frame position and orientation relative to the base frame','All possible joint angles for a required tool pose','Actuator torque for a desired acceleration','A contact force from a sensor voltage'],0,'Forward kinematics maps a joint-space description to the tool pose in Cartesian space relative to the base.', ['This is the specified input-to-output direction.','This is inverse kinematics.','This concerns dynamics.','This is not the defined kinematics mapping.'],'Forward: joints to pose.',typ='definition',difficulty='easy')
add(31,'Inverse kinematics','A required end-effector position and orientation are given; which problem seeks joint angles that attain them?', ['Inverse kinematics','Forward kinematics','Inverse dynamics','Forward dynamics'],0,'Inverse kinematics starts with a desired pose and seeks joint configurations.', ['This matches the specified input and output.','Forward kinematics starts with joint variables.','Inverse dynamics seeks forces/torques for motion.','Forward dynamics seeks motion from forces/torques.'],'Inverse: pose to joints.',typ='scenario')
add(31,'Inverse kinematics ambiguity','Which statement correctly reflects the inverse-kinematics discussion?', ['A desired pose may have no solution, one solution or multiple solutions','Every desired pose has exactly one closed-form solution','Nonlinear equations guarantee infinitely many solutions for every pose','If a closed-form solution is hard to obtain, the robot has no workspace'],0,'The source raises both existence and multiple solutions and says nonlinear equations may be difficult or impossible to solve in closed form.', ['This preserves existence and multiplicity without an unjustified universal claim.','The source explicitly rejects the guarantee implicit here.','Nonlinearity alone does not imply infinitely many solutions.','Difficulty of symbolic solution is not the same as geometric unreachability.'],typ='conceptual',difficulty='hard')
add(31,'Workspace','If no feasible joint configuration realizes a desired pose under the kinematic model, what follows?', ['That pose is outside the modeled attainable workspace','The Jacobian must be invertible everywhere','The desired pose is necessarily reached by increasing speed','Forward kinematics is undefined for all joint configurations'],0,'The workspace is tied to the existence of an inverse-kinematic solution for the desired position and orientation.', ['This is the conclusion stated on the slide.','No such claim about all Jacobians follows.','Changing speed does not create a missing kinematic configuration.','A missing inverse solution for one pose does not invalidate forward kinematics elsewhere.'],typ='scenario')
add(32,'Jacobian velocity mapping','Which mapping is represented by the manipulator Jacobian on the slide?', ['Joint velocities to Cartesian velocities','Joint positions directly to material density','Cartesian acceleration directly to software cost','Joint torques directly to a unique pose'],0,'The slide specifies a velocity mapping from joint space to Cartesian space.', ['This is the stated Jacobian mapping.','Material density is not the Jacobian output.','Neither quantity matches the stated mapping.','The slide does not define a torque-to-pose map.'],typ='definition')
add(32,'Jacobian singularity','What property is assigned to singular configurations in the slide?', ['The stated Jacobian velocity mapping is not invertible','All joint velocities must physically be zero','Every desired pose has exactly one inverse solution','The robot loses every possible motion direction'],0,'At a singularity the mapping is not invertible; that does not imply that every motion is impossible.', ['This is the property explicitly stated.','Noninvertibility does not require zero joint velocity.','Singularity does not guarantee unique inverse kinematics.','Loss of invertibility is not the same as loss of all motion.'],typ='conceptual',difficulty='hard')
add(32,'Jacobian force mapping','In the displayed force relation, how are joint torques related to the Cartesian wrench expressed in the same frame?', ['τ = Jᵀ F','τ = J + F','τ = J F for every Jacobian shape','τ = F / J element by element'],0,'The slide displays τ = JᵀF; the transpose is essential to the stated relation.', ['This is the displayed relation.','Matrix addition does not represent the given mapping.','The slide uses the transpose, not an unrestricted untransposed product.','Elementwise division is not the stated operation.'],typ='definition',assumptions=['Use the source’s matched-frame wrench and Jacobian convention.'])
add(32,'Jacobian calculation','For v = J q̇, let J = diag(2, 3) and q̇ = (1, −2)ᵀ; what is v?', ['(2, −6)ᵀ','(2, 6)ᵀ','(3, 1)ᵀ','(0.5, −2/3)ᵀ'],0,'Multiplication by the diagonal Jacobian scales the components: 2×1 and 3×(−2).', ['The two products give 2 and −6.','This loses the negative sign in the second component.','This incorrectly adds diagonal values to the input.','This applies the inverse diagonal scaling instead.'],'Rows of J multiply the joint-rate vector.',typ='numerical',difficulty='medium',assumptions=['This is a generated two-coordinate numerical illustration of the cited relation.','Use compatible normalized units.'],steps=['v₁ = 2×1 + 0×(−2) = 2.','v₂ = 0×1 + 3×(−2) = −6.'],formulas=[{'expression':'v = J q̇','variables':{'v':'Cartesian velocity vector','J':'Jacobian','q̇':'joint velocity vector'},'units':{'v':'normalized velocity units','q̇':'compatible normalized joint-rate units'},'assumptions':['The numerical J is given and is not a general constant robot Jacobian.']}])
add(32,'Transpose calculation','For τ = JᵀF, let J = [[1, 2], [0, 3]] and F = (4, 5)ᵀ; what is τ?', ['(4, 23)ᵀ','(14, 15)ᵀ','(4, 15)ᵀ','(9, 10)ᵀ'],0,'Transpose J before multiplication: Jᵀ = [[1,0],[2,3]], so the result is (4,23)ᵀ.', ['This uses the transpose and both terms in the second row.','This multiplies JF rather than JᵀF.','This omits the 2×4 contribution.','This is not the specified matrix product.'],typ='numerical',difficulty='hard',assumptions=['Generated two-coordinate illustration of the slide’s transpose relation.','Use compatible normalized units and the same reference frame.'],steps=['Jᵀ = [[1,0],[2,3]].','τ₁ = 1×4+0×5 = 4.','τ₂ = 2×4+3×5 = 23.'],formulas=[{'expression':'τ = JᵀF','variables':{'τ':'joint generalized force vector','J':'Jacobian','F':'Cartesian generalized force vector'},'units':{'τ':'compatible normalized generalized force units','F':'compatible normalized force units'},'assumptions':['Use the stated matched-frame convention.']}])
add(33,'Dynamics','What distinguishes dynamics from kinematics in the introduction?', ['Dynamics studies forces required to cause motion','Dynamics excludes all forces and treats only geometry','Dynamics is only the naming of coordinate frames','Dynamics guarantees motion without actuator effort'],0,'Dynamics studies the forces causing motion, whereas kinematics treats motion without regard to those forces.', ['This is the stated distinction.','This instead describes the force-independent focus of kinematics.','Frames are part of spatial description, not a complete dynamics definition.','The source discusses required actuator torque functions.'],typ='definition',more_pages=[28])
add(33,'Torque dependencies','Select all factors listed as influencing required actuator torque functions.', ['The spatial and temporal attributes of the path','Mass properties of links and payload','Friction in joints','Only the final pose, regardless of timing or payload'],[0,1,2],'The source explicitly lists path geometry/timing, mass properties and friction.', ['Spatial and temporal path attributes are named.','Both link and payload mass properties are named.','Joint friction is named.','The stated dependencies show why final pose alone is insufficient.'],typ='statement')
add(34,'Direct and inverse dynamics','Which matching is correct for the two dynamics problems described?', ['Inverse: desired motion to torque; direct: torque to acceleration and motion','Inverse: torque to motion; direct: desired motion to torque','Both compute only coordinate-frame names','Both guarantee zero torque at nonzero acceleration'],0,'The slide identifies required torque for desired motion as inverse dynamics and acceleration from torque as the direct problem.', ['Both directions match the source.','The directions are reversed.','Neither problem is merely frame naming.','No zero-torque guarantee is stated.'],typ='match')
add(35,'Trajectory coordination','What timing choice commonly makes joint motion appear coordinated?', ['The joints start and end their motions at the same times','Every joint must follow the same angular displacement','Every joint must have the same torque throughout','The joints must finish one after another'],0,'The slide says joints commonly share start and finish times; it does not require equal displacements or torque.', ['This is the stated timing coordination.','Different joints can follow different trajectories.','The source does not equate coordination with equal torque.','Sequential finishes are not the common coordination rule described.'],typ='conceptual')
add(35,'Via points','In trajectory generation, what are via points?', ['Intermediate locations that the manipulator must pass through','Only the final desired destination','The manufacturer’s calibration invoice','Points that must always be avoided'],0,'Via points constrain intermediate locations along the route to a destination.', ['This is the slide’s definition.','Via points are distinguished from the final destination.','This is unrelated to trajectory geometry.','The source says the manipulator passes through them.'],typ='definition',difficulty='easy')
add(36,'Design requirements','Which pair of structural outcomes is influenced by the listed manipulator design choices?', ['Workspace size and structural stiffness','Only the color and logo','Only the programming language syntax','Guaranteed infinite payload and speed'],0,'The slide states that design factors affect workspace size and manipulator stiffness.', ['Both are explicitly named outcomes.','Color/logo are not the structural outcomes described.','The factors include mechanics, not only syntax.','The slide names trade-offs, not unlimited capabilities.'],typ='conceptual')
add(36,'Design factors','Which group contains only factors listed for manipulator design?', ['Size, speed, load capability and joint arrangement','Only font choice, screen size and web traffic','Only link color and naming style','Only final pose, with no actuator or sensor choices'],0,'The slide lists size, speed, load capability, joint number/geometry, actuator location, transmission and sensors.', ['All four belong to the listed considerations.','These do not match the mechanical design factors.','These omit the functional design factors.','Actuator and sensor choices are explicitly included.'],typ='definition')
add(37,'Joint-count trade-off','What trade-off does the slide associate with adding joints to an arm?', ['More dexterity but greater construction difficulty and expense','Less expense and no change in capability in every case','Guaranteed perfect accuracy with no design cost','Elimination of transmission and sensor choices'],0,'The slide pairs increased dexterity/capability with harder construction and higher cost.', ['This preserves both benefit and cost.','This contradicts the stated cost increase.','The source does not promise perfect accuracy.','The slide still lists transmission and sensors as design issues.'],typ='conceptual')
add(38,'Specialized assembly arm','In the flat-circuit-board example, what task is assigned to the fourth joint?', ['Rotate the grasped component about a vertical axis','Provide the first of three translational positioning coordinates','Guarantee arbitrary orientation about all three axes by itself','Measure the component’s electrical resistance'],0,'Three joints provide position in 3D; the fourth adds rotation about a vertical axis for the specialized task.', ['This is the stated fourth-joint role.','Position is assigned to the first three joints in the example.','A single added axis is not arbitrary three-axis orientation.','The fourth joint is a motion element, not this measurement.'],typ='scenario')
add(38,'Task constraints','Why can the stated circuit-board placement task use four joints when a generic full-pose task is assigned six?', ['The specialized task needs fewer independent orientation choices','The task no longer needs any spatial position','Every four-joint arm can realize every possible 3D pose','Six-DOF motion is impossible in physical space'],0,'The specialized example requires position plus rotation about a vertical axis, rather than arbitrary orientation.', ['This explains the differing task requirements.','The slide retains three-dimensional positioning.','The claim confuses task-specific sufficiency with universal pose freedom.','The source explicitly discusses six DOF for generic tasks.'],typ='conceptual',difficulty='hard',more_pages=[22])
add(39,'Control versus dynamics','Why does knowing the dynamics not by itself solve the position-control problem?', ['Control must also compensate model-parameter errors and suppress disturbances','Dynamics contains no information useful to control','A trajectory is followed automatically whenever an equation exists','Sensors can never contribute to motion control'],0,'The slide calls dynamics central but not sufficient; the controller must address parameter error and disturbances.', ['These are the two stated control concerns.','The source calls dynamics central, not useless.','An equation does not itself implement the required control.','The next slide explicitly uses sensor feedback.'],typ='conceptual',difficulty='hard',more_pages=[40])
add(40,'Feedback control','Which signal path matches the described position-control loop?', ['Joint position/velocity sensors → control algorithm → actuator torque commands','Actuator torque commands → no sensing → guaranteed exact trajectory','A fixed list of colors → joint sensors → payload mass','Joint sensors → only a printed report, never actuator commands'],0,'The algorithm monitors position and velocity sensing and computes torque commands to keep the manipulator on course.', ['This follows the stated feedback-to-command path.','This removes the stated feedback and adds an unsupported guarantee.','This path is unrelated to the described loop.','The source explicitly says the algorithm computes actuator torque commands.'],typ='sequence')
add(41,'Linear and nonlinear models','Which statement accurately reports the slide’s control-model discussion without inventing a universal guarantee?', ['Approximate linear models are common, and accounting for nonlinear dynamics can improve performance','Linear models represent every manipulator exactly at every state','Nonlinear modeling always removes all disturbances and uncertainty','Linear control never appears in industrial robots'],0,'The slide contrasts common approximate linear models with performance benefits from considering nonlinear dynamics; it does not establish unconditional perfect control.', ['This preserves the intended comparison and its limits.','The word approximate contradicts an everywhere-exact claim.','No complete removal of uncertainty is stated.','The slide says such models are popular.'],typ='statement')
add(42,'Position and force control','Which pairing follows the slide’s basic distinction?', ['Free-space motion → position control; contact interaction → force control','Free-space motion → force control only; contact → position control only','All contact tasks require zero force','Force control makes position control irrelevant in every direction'],0,'The slide associates free-space motion with position control and contact with force control, then combines them in a hybrid scheme.', ['This is the stated introductory pairing.','This reverses the given association.','Contact-force regulation does not mean zero force in every task.','The slide explicitly describes complementary control across directions.'],typ='match')
add(42,'Hybrid control','In the described hybrid control problem, how are force and position laws used?', ['Position is controlled in some directions and force in the remaining directions','Both must command contradictory values of the same constrained variable without a rule','Force control eliminates every position target','Position control is used only after all contact has ended'],0,'The slide partitions directions between position-control and force-control laws.', ['This matches the stated direction-wise division.','This is not the described complementary division.','The hybrid scheme retains position-controlled directions.','The slide permits position control alongside contact-force regulation.'],typ='conceptual',difficulty='hard')
add(43,'Window-washing example','For the window-washing example, what must be controlled perpendicular and tangent to the glass, respectively?', ['Perpendicular: force; tangent: motion trajectory','Perpendicular: motion only; tangent: constant force only','Perpendicular: zero sensing; tangent: no movement','Both directions: arbitrary force without any trajectory'],0,'The source specifies force normal to the glass while following a trajectory tangent to it.', ['This is the exact directional allocation in the example.','This reverses the stated allocation.','The example requires controlled force and motion.','The example explicitly retains a tangential trajectory.'],'Press into the glass; move along the glass.',typ='scenario',difficulty='hard')
add(44,'Robot programming','What function does a robot programming language serve in the slide?', ['An interface between the human user and the industrial robot','A substitute for every mechanical link','A guarantee that no force control is needed','A method that always requires the physical robot during program development'],0,'The slide defines the language as the human–robot interface and distinguishes offline development from direct physical access.', ['This is the stated role.','A language does not replace mechanical structure.','The source does not remove force-control requirements.','The slide explicitly describes offline development without robot access.'],typ='definition')
add(44,'Programmability','What distinction does the slide draw between manipulators and fixed automation?', ['Manipulators are flexible in the sense of being programmable','All manipulators must have mechanically flexible links','Fixed automation is always more intelligent than every robot','Manipulators cannot change their task'],0,'Here flexible means programmable, not necessarily elastic mechanical links.', ['This matches the explicitly explained meaning.','This confuses program flexibility with structural flexibility.','This comparison is not stated.','Programmability enables task changes rather than forbidding them.'],'Flexible program ≠ flexible metal.',typ='conceptual',difficulty='hard')
add(44,'Offline programming','What makes the described system an offline robot-programming environment?', ['Programs can be developed through a graphics-supported environment without access to the robot','The robot must be manually stopped and guided for every program edit','No computer graphics can be used','All programs must be written while physically holding the end-effector'],0,'The source defines offline programming through computer-graphics support and development without accessing the physical robot.', ['This captures both stated features.','This is not the defining no-access advantage.','Computer graphics is explicitly part of the description.','Physical guidance is not required by the offline description.'],typ='definition',more_pages=[47])
add(45,'Offline programming benefits','Select all benefits that the slide associates with offline programming.', ['The production robot need not be tied up for reprogramming','CAD data can connect design information with manufacturing','Direct CAD use can reduce programming time in some cases','It guarantees that every physical process is safe without validation'],[0,1,2],'The slide discusses reduced equipment downtime, CAD integration and possible programming-time savings, not automatic physical safety.', ['This is the first stated benefit.','This is an explicitly stated design-to-manufacturing link.','The wording correctly retains in some cases.','No automatic safety guarantee is stated.'],typ='statement')
add(46,'Programming content','Which set can be described in a robot programming language according to the slide?', ['Desired motions, contact forces and manipulation strategies','Only the end-effector’s color','Only a list of joint names, never motion','Only software installation dates'],0,'The slide explicitly includes desired manipulator/end-effector motion, desired contact forces and complex strategies.', ['Every listed category is supported.','The source lists functional behaviors, not only appearance.','The source explicitly includes motion.','These dates are not the stated program contents.'],typ='definition')

